  // Validate the app selection before anything expensive happens.
  selectDevServers(options.apps);

  const stateDir = stateDirFor(instance);
  const envFile = envFileFor(instance);
  const seededMarker = seededMarkerFor(instance);
  const realmHashMarker = realmHashMarkerFor(instance);

  if (options.fresh) {
    clearFreshState({ seededMarker, realmHashMarker });
