    // seeded marker already reasons about) survives from an earlier run — the one condition under
    // which `start-dev --import-realm` silently keeps the realm already in there instead of picking
    // up what was just rendered (see `realm-drift.mjs`). Check before doing anything expensive
    // (pnpm install, the backend image build): a stale realm always means broken login, so there is
    // nothing to gain from discovering that four minutes later.
    const outcome = compareRealmHash({
      storedHash: readStoredRealmHash(instance),
      freshHash: hashRealm(renderedRealm),
    });
    if (outcome === 'drift') {
      throw new Error(realmDriftMessage(instance));
    } else if (outcome === 'bootstrap') {
